import{_ as n,C as l,o,c as r,j as i,E as s,a as e,a2 as d}from"./chunks/framework.C21TwvGF.js";const p=JSON.parse('{"title":"2-hafta","description":"","frontmatter":{"title":"2-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"9-sinf (IoT)","link":"/9-sinf-iot/"},"n":2,"bob":"I-bob · IoT asoslari va virtual laboratoriya","lessons":[{"g":4,"title":"4-dars: Tinkercad.com virtual laboratoriyasida ro‘yxatdan o‘tish va interfeys","lead":"Tinkercad.com virtual laboratoriyasida ro‘yxatdan o‘tish va interfeys","link":"/9-sinf-iot/hafta-02/dars-1","slide":"/slaydlar/9-sinf-iot/hafta-02/dars-1.html","test":"/slaydlar/9-sinf-iot/hafta-02/dars-1-test.html"},{"g":5,"title":"5-dars: Tinkercad muhitida virtual elektron komponentlar bilan ishlash","lead":"Tinkercad muhitida virtual elektron komponentlar bilan ishlash","link":"/9-sinf-iot/hafta-02/dars-2","slide":"/slaydlar/9-sinf-iot/hafta-02/dars-2.html","test":"/slaydlar/9-sinf-iot/hafta-02/dars-2-test.html"},{"g":6,"title":"6-dars: Elektron sxema asosida bitta LED lampaning ishlash prinsipi va ulanishi","lead":"Elektron sxema asosida bitta LED lampaning ishlash prinsipi va ulanishi","link":"/9-sinf-iot/hafta-02/dars-3","slide":"/slaydlar/9-sinf-iot/hafta-02/dars-3.html","test":"/slaydlar/9-sinf-iot/hafta-02/dars-3-test.html"}],"test":"/slaydlar/9-sinf-iot/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"9-sinf-iot/hafta-02/index.md","filePath":"9-sinf-iot/hafta-02/index.md"}'),h={name:"9-sinf-iot/hafta-02/index.md"},u={class:"blk"},m={id:"uyga-vazifa",tabindex:"-1"};function c(k,a,g,f,y,b){const t=l("Icon");return o(),r("div",null,[i("div",u,[i("h2",m,[s(t,{name:"house"}),a[0]||(a[0]=e(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h3 id="_4-dars-tinkercad-com-virtual-laboratoriyasida-ro-yxatdan-o-tish-va-interfeys" tabindex="-1">4-dars: Tinkercad.com virtual laboratoriyasida ro‘yxatdan o‘tish va interfeys <a class="header-anchor" href="#_4-dars-tinkercad-com-virtual-laboratoriyasida-ro-yxatdan-o-tish-va-interfeys" aria-label="Permalink to &quot;4-dars: Tinkercad.com virtual laboratoriyasida ro‘yxatdan o‘tish va interfeys&quot;">​</a></h3><ol><li>Tinkercad.com saytidagi shaxsiy profilingizga kiring va &quot;Circuits&quot; bo&#39;limida yangi loyiha yarating. Unga <code>9-sinf_UygaVazifa_4</code> nomini bering.</li><li>Ish maydoniga kamida 4 ta turli komponentni joylashtiring (masalan: Arduino Uno, kichik Breadboard, LED, 9V batareya).</li><li>&quot;Rotate&quot; (R) asbobi yordamida breadboardni 90 gradusga buring, &quot;Notes&quot; (N) asbobi yordamida har bir komponent yoniga uning vazifasini bildiruvchi matnli yorliq biriktiring.</li><li>&quot;Send To&quot; / &quot;Share&quot; orqali sxemangizning ommaviy havolasini (Public Share link) oling va havola to&#39;g&#39;ri ochilayotganini tekshiring.</li></ol><hr><h3 id="_5-dars-tinkercad-muhitida-virtual-elektron-komponentlar-bilan-ishlash" tabindex="-1">5-dars: Tinkercad muhitida virtual elektron komponentlar bilan ishlash <a class="header-anchor" href="#_5-dars-tinkercad-muhitida-virtual-elektron-komponentlar-bilan-ishlash" aria-label="Permalink to &quot;5-dars: Tinkercad muhitida virtual elektron komponentlar bilan ishlash&quot;">​</a></h3><ol><li>Breadboard ustida 9V batareya, suriluvchi kalit (Slide switch), 330 Om rezistor va sariq LED dan iborat mustaqil yopiq elektr zanjirini yig&#39;ing.</li><li>Zanjirga virtual multimetrni &quot;Voltage&quot; rejimida ulab, sariq LED uchlaridagi kuchlanish tushuvini (Volt) o&#39;lchang.</li><li>Ikkinchi multimetrni &quot;Amperage&quot; rejimida zanjirga ketma-ket ulab, zanjirdan o&#39;tayotgan tok kuchini (milliAmper — mA) aniqlang.</li><li>Rezistor qiymatini 1 kOm ga oshiring va tok kuchi hamda yorug&#39;lik intensivligi qanday o&#39;zgarganini 2 ta jumla bilan tahlil qiling.</li></ol><hr><h3 id="_6-dars-elektron-sxema-asosida-bitta-led-lampaning-ishlash-prinsipi-va-ulanishi" tabindex="-1">6-dars: Elektron sxema asosida bitta LED lampaning ishlash prinsipi va ulanishi <a class="header-anchor" href="#_6-dars-elektron-sxema-asosida-bitta-led-lampaning-ishlash-prinsipi-va-ulanishi" aria-label="Permalink to &quot;6-dars: Elektron sxema asosida bitta LED lampaning ishlash prinsipi va ulanishi&quot;">​</a></h3><ol><li>Arduino Uno platasining <code>D9</code> raqamli piniga 220 Om rezistor orqali bitta qizil LED ni ulang va katodini Arduino <code>GND</code> ga bog&#39;lang.</li><li>Tinkercad &quot;Code&quot; panelida C++ tilida quyidagi mantiqqa ega dastur yozing: <ul><li>LED 1 soniya yonsin;</li><li>500 millisekund o&#39;chsin;</li><li>LED 2 soniya yonsin;</li><li>1 soniya o&#39;chsin;</li><li>Tsikl cheksiz takrorlansin.</li></ul></li><li>Nima uchun 5V quvvatda ishlaydigan Arduino uchun 220 Om rezistor tanlanganini Om qonuni formulasi ($R = (5\\text{V} - 2\\text{V}) / 0.015\\text{A}$) asosida yozma asoslab bering.</li></ol><hr>',11))])])}const q=n(h,[["render",c]]);export{p as __pageData,q as default};
